INSERT INTO hecho (id_tipo_hecho, id_ubicacion, fecha_hecho) SELECT (SELECT id_tipo_hecho FROM tipo_hecho WHERE UPPER(TRIM(nombre)) = UPPER('hecho_delictivo') ROWS 1), p.id_origen, '2023-12-10' FROM persona p WHERE p.nombres = 'AGR_2023_399681' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho h JOIN involucrado_hecho ih ON ih.id_hecho = h.id_hecho WHERE ih.id_involucrado = p.id_persona   AND h.fecha_hecho = '2023-12-10');
